export type KitchenSinkCompanyData = {
    body: {
        /**
         * Your Fiber API key
         */
        apiKey: string;
        /**
         * A unique identifier for the company. Accepts one of: linkedinSlug, linkedinUrl, or linkedinOrgID. Providing this increases the accuracy and speed of the lookup. If this is provided, you do not need to supply companyName or companyDomain.
         */
        companyIdentifier?: {
            identifier: 'linkedinSlug';
            /**
             * The LinkedIn slug of the person's current company.
             */
            value: string;
        } | {
            identifier: 'linkedinUrl';
            /**
             * The LinkedIn URL of the person's current company.
             */
            value: string;
        } | {
            identifier: 'linkedinOrgID';
            /**
             * The LinkedIn organization ID of the person's current company.
             */
            value: string;
        } | null;
        companyName?: {
            /**
             * The name of the company. All input words must match.
             */
            value?: string | null;
        } | null;
        companyDomain?: {
            /**
             * The domain of the company. URL prefixes (https, www) are automatically stripped. Subdomains and path segments are preserved to support domains like 'instagram.com/company' or 'my_company.netlify.app'.
             */
            value?: string | null;
        } | null;
        /**
         * Maximum number of company results to return. Sorted by best match. Defaults to 1.
         */
        numCompanies?: number;
    };
    path?: never;
    query?: never;
    url: '/v1/kitchen-sink/company';
};

